    void addAidMsg(int cardType,String strAID_IC,String packageName ){
        List<String> aidList_AID_IC = new ArrayList<>(Arrays.asList(strAID_IC.split("\n")));
        Log.e("szaf", "onClick aidList.size(): "+aidList_AID_IC.size() );
        try {
            int ret =mEmvBinderService.saveAidMsg(cardType,aidList_AID_IC, packageName);
            if (ret == 0){
                appendText("save AID  is success !");
            }else {
                appendText("save AID is ERROR");
            }
        } catch (RemoteException e) {
            e.printStackTrace();
        }
        Log.e("szaf", "onClick: " + aidList_AID_IC);
    }


    void queryAidMsg(int cardType,String packageName){
        try {
            LogUtils.e("queryAidMsg packageName : "+ packageName);
            String getStrAID = mEmvBinderService.queryAIDMsg(cardType,packageName);
            if (TextUtils.isEmpty(getStrAID)){
                Toast.makeText(AidInterfaceActivity.this, "AID is not written, please write first", Toast.LENGTH_SHORT)
                        .show();
            }else {
                Intent intent= new Intent(this, AidListActivity.class);
                intent.putExtra("cardType" ,cardType);
                intent.putExtra("packageName",packageName);
                startActivity(intent);
            }
        } catch (RemoteException e) {
            e.printStackTrace();
        }
    }
